@php($chartData = \Illuminate\Support\Arr::only($production, ['trend', 'states', 'mines', 'shifts']))
<script>
document.addEventListener('DOMContentLoaded', () => {
    if (typeof window.Chart !== 'function') { document.getElementById('jmv-chart-status').hidden = false; return; }
    const data = @json($chartData);
    const base = {responsive: true, maintainAspectRatio: false, animation: false, plugins: {legend: {position: 'bottom', labels: {usePointStyle: true, boxWidth: 8, font: {size: 11}}}}, scales: {x: {grid: {display: false}, ticks: {maxTicksLimit: 8, font: {size: 10}}}, y: {beginAtZero: true, ticks: {precision: 0}, grid: {color: '#f1f5f9'}}}};
    new window.Chart(document.getElementById('jmv-trend'), {type: 'line', data: {labels: data.trend.map(p => p.date), datasets: [{label: 'Actual coal', data: data.trend.map(p => p.coal), borderColor: '#24477f', backgroundColor: 'rgba(36,71,127,.08)', fill: true, tension: .25, pointRadius: 2}, {label: 'Saved target', data: data.trend.map(p => p.target), borderColor: '#d97706', borderDash: [5, 5], spanGaps: false, pointRadius: 2}]}, options: base});
    const counts = Object.values(data.states), empty = !counts.some(Boolean);
    new window.Chart(document.getElementById('jmv-workflow'), {type: 'doughnut', data: {labels: empty ? ['No logs'] : @json(array_values(\App\Models\JmvDailyProductionLog::STATUSES)), datasets: [{data: empty ? [1] : counts, backgroundColor: empty ? ['#e2e8f0'] : ['#94a3b8', '#f59e0b', '#e11d48', '#059669'], borderWidth: 3}]}, options: {responsive: true, maintainAspectRatio: false, animation: false, cutout: '72%', plugins: {legend: {display: false}, tooltip: {enabled: !empty}}}});
    new window.Chart(document.getElementById('jmv-mines'), {type: 'bar', data: {labels: data.mines.map(p => p.name), datasets: [{label: 'Coal', data: data.mines.map(p => p.coal), backgroundColor: '#24477f', borderRadius: 5, maxBarThickness: 35}, {label: 'Soil', data: data.mines.map(p => p.soil), backgroundColor: '#fbbf24', borderRadius: 5, maxBarThickness: 35}]}, options: base});
    new window.Chart(document.getElementById('jmv-shifts'), {type: 'bar', data: {labels: Object.keys(data.shifts), datasets: [{label: 'Coal', data: Object.values(data.shifts), backgroundColor: '#24477f', borderRadius: 5, maxBarThickness: 25}]}, options: {...base, indexAxis: 'y', plugins: {legend: {display: false}}, scales: {x: {beginAtZero: true, ticks: {precision: 0}, grid: {color: '#f1f5f9'}}, y: {grid: {display: false}, ticks: {font: {size: 10}}}}}});
});
</script>
@endpush
